// French C1 practice rooms: 6 modules x 12 rooms x 3 questions.
window.frRooms = window.frRooms || {};
frRooms.C1 = [
  // Module 1: Nuance & Subtle Meaning
  [
    {t:"Hedging words",s:"Vocabulary",qs:[
      {q:"'il semblerait que' means:",opts:["it would seem that","it is certain that","it was obvious that","it should be that"],a:0,ex:"Semblerait is the conditional of sembler, which turns a statement into a cautious impression."},
      {q:"Which word means 'alleged', as in 'le ___ coupable'?",opts:["prétendu","prétentieux","prétendant","prévenant"],a:0,ex:"Prétendu(e) casts doubt on a label; prétentieux means pretentious, a classic false friend."},
      {q:"'sous-jacent' in 'le problème sous-jacent' means:",opts:["underlying","minor","recurring","recent"],a:0,ex:"Sous-jacent (lying beneath) describes a deeper cause that is not immediately visible."}]},
    {t:"Doubt, limits and qualifiers",s:"Vocabulary",qs:[
      {q:"Which nuance does 'soi-disant' add in 'un soi-disant expert'?",opts:["the speaker doubts the title","the expert is very famous","the expert is self-taught","the title is official"],a:0,ex:"Soi-disant (so-called) signals scepticism: the person claims the title, the speaker doubts it."},
      {q:"'Reste à savoir s'il acceptera.' means:",opts:["It remains to be seen whether he'll accept.","He still has to learn how to accept.","We know he will accept in the end.","He stayed to find out if he'd accept."],a:0,ex:"Reste à savoir si flags an open question: the outcome is still uncertain."},
      {q:"Odd one out: which qualifier does NOT soften or limit a statement?",opts:["tout à fait","plutôt","dans une certaine mesure","quelque peu"],a:0,ex:"Tout à fait reinforces (completely); plutôt, quelque peu and dans une certaine mesure weaken or limit a claim."}]},
    {t:"Sounds of nuance",s:"Pronunciation",qs:[
      {q:"Listen. How is the 'qu' in 'quasiment' pronounced?",say:"quasiment",opts:["like k","like kw","like ch","like g"],a:0,ex:"In quasiment, qu is a simple k sound [ka-zi-mɑ̃], and the s between vowels sounds like z."},
      {q:"Listen. In 'sous-jacent', how is the s at the end of 'sous' pronounced?",say:"sous-jacent",opts:["silent","like z","like s","like sh"],a:0,ex:"The final s of sous is silent before a consonant: [su-ʒa-sɑ̃]; jacent starts with a soft j."},
      {q:"Listen. Which syllable of 'semblerait' carries the main stress?",say:"Il semblerait que",opts:["the last: -rait","the first: sem-","the middle: -ble-","the first two equally"],a:0,ex:"French stresses the last pronounced syllable of a word or rhythm group, so semblerait is stressed on -rait."}]},
    {t:"C'est ... qui / que",s:"Grammar",qs:[
      {q:"Complete to highlight the person: 'C'est Marie ___ a trouvé la solution.'",opts:["qui","que","dont","où"],a:0,ex:"When the highlighted element is the subject of the verb, French uses c'est ... qui."},
      {q:"Complete: 'C'est à Lyon ___ elle a fait ses études.'",opts:["que","qui","où","dont"],a:0,ex:"With a highlighted place or time complement, standard French uses c'est ... que, not où."},
      {q:"Complete: 'C'est moi qui ___ raison.'",opts:["ai","a","as","avons"],a:0,ex:"After c'est moi qui, the verb agrees with moi in the first person: c'est moi qui ai raison."}]},
    {t:"Mood and the conditionnel",s:"Grammar",qs:[
      {q:"'Il paraît qu'il ___ démissionné.' (a rumour)",opts:["a","ait","eût","aie"],a:0,ex:"Il paraît que reports hearsay as information and takes the indicative, not the subjunctive."},
      {q:"Which sentence presents the news as unconfirmed?",opts:["Le ministre aurait démissionné hier.","Le ministre a démissionné hier.","Le ministre avait démissionné hier.","Le ministre démissionna hier."],a:0,ex:"The conditionnel passé (aurait démissionné) is the standard way to report an unconfirmed fact."},
      {q:"'Je ne suis pas sûr qu'il ___ la vérité.'",opts:["dise","dit","dira","disait"],a:0,ex:"Ne pas être sûr que expresses doubt, which triggers the subjunctive (dise)."}]},
    {t:"Reading: reading between the lines",s:"Reading",qs:[
      {q:"Read: 'Certes, le projet est ambitieux ; reste à savoir s'il sera financé.' What does the writer suggest?",opts:["The funding is still uncertain.","The project is fully funded.","The project lacks ambition.","The writer rejects the project."],a:0,ex:"Certes grants a point, and reste à savoir si raises an open question about the funding."},
      {q:"Read: 'Les ventes ont à peine progressé ; la direction est plutôt inquiète.' Which is true?",opts:["Sales barely rose and managers are fairly worried.","Sales rose sharply and managers are calm.","Sales fell and managers are very angry.","Sales hardly fell and managers are relieved."],a:0,ex:"À peine means barely, and plutôt (rather) tones inquiète down to 'fairly worried'."},
      {q:"Read: 'Ce prétendu remède miracle n'a, semble-t-il, aucun effet prouvé.' What is the writer's attitude?",opts:["sceptical","enthusiastic","neutral","indifferent"],a:0,ex:"Prétendu and the ironic 'remède miracle' cast doubt; semble-t-il adds caution but keeps the criticism."}]},
    {t:"Listening: how sure are they?",s:"Listening",qs:[
      {q:"Listen. How certain is the speaker about the meeting?",say:"Il semblerait que la réunion soit reportée à jeudi.",opts:["not fully certain","completely certain","certain it is cancelled","the meeting isn't mentioned"],a:0,ex:"Il semblerait que presents the information cautiously; the speaker is not stating a confirmed fact."},
      {q:"Listen. Who had the idea?",say:"C'est mon collègue qui a eu l'idée, pas moi.",opts:["the speaker's colleague","the speaker","the speaker's boss","nobody knows"],a:0,ex:"C'est ... qui focuses on mon collègue, and 'pas moi' contrasts him with the speaker."},
      {q:"Listen. How far does the speaker agree?",say:"Dans une certaine mesure, je partage votre avis.",opts:["partly","completely","not at all","they refuse to say"],a:0,ex:"Dans une certaine mesure limits the agreement: only up to a point."}]},
    {t:"Diplomatic replies",s:"Speaking",qs:[
      {q:"A colleague asks you to take on an extra project. Which reply refuses most diplomatically?",opts:["J'aimerais beaucoup, mais je crains de ne pas pouvoir cette fois.","Non, je ne veux pas le faire, j'ai déjà bien trop de travail.","Pas question, demandez donc à quelqu'un d'autre de le faire.","Je refuse, ce n'est pas du tout mon travail, désolé."],a:0,ex:"The conditionnel (j'aimerais) and je crains de soften the refusal and protect the relationship."},
      {q:"In a debate you want to concede a point before objecting. You say:",opts:["Certes, vous avez raison sur ce point, mais...","Vous avez tort sur absolument tout, car...","Je suis entièrement d'accord, donc...","Peu importe ce que vous dites, puisque..."],a:0,ex:"Certes ... mais grants part of the opponent's view before introducing a reservation."},
      {q:"You want to soften 'Votre rapport est faux.' Which is most nuanced?",opts:["Certains chiffres me semblent discutables.","Votre rapport est complètement faux.","Votre rapport ne vaut rien du tout.","Il y a des erreurs partout ici."],a:0,ex:"Me semblent and discutables hedge the criticism and limit it to some figures only."}]},
    {t:"Writing nuanced sentences",s:"Writing",qs:[
      {q:"Choose the correctly written sentence.",opts:["C'est nous qui avons pris la décision.","C'est nous qui ont pris la décision.","C'est nous que avons pris la décision.","C'est nous qui avez pris la décision."],a:0,ex:"In c'est nous qui, the verb agrees with nous: avons."},
      {q:"Fill the gap: 'Il est ___ possible que le vol soit annulé.' (= entirely)",opts:["tout à fait","à peine","quasiment pas","plutôt peu"],a:0,ex:"Tout à fait means entirely and strengthens the adjective; the other options weaken it."},
      {q:"Choose the correctly written hedged sentence.",opts:["Il semblerait que le prix ait baissé.","Il semblerait que le prix est baissé.","Il sembleré que le prix ait baissé.","Il semblerais que le prix ait baissé."],a:0,ex:"Semblerait is third person conditional, and baisser forms its compound tenses with avoir (ait baissé)."}]},
    {t:"Understatement and caution",s:"Culture",qs:[
      {q:"Why do French news reports often say 'le ministre aurait menti' rather than 'a menti'?",opts:["to avoid stating an unproven claim as fact","because it is more polite to readers","because the passé composé is informal","to show the event lies in the future"],a:0,ex:"The 'conditionnel journalistique' lets media report allegations without asserting them, partly for legal caution."},
      {q:"In everyday French, 'C'est pas mal du tout !' usually means:",opts:["it's actually quite good","it's really rather bad","it's absolutely perfect","it's morally wrong"],a:0,ex:"This litote understates praise: saying 'not bad' typically means 'good', a common form of French restraint."},
      {q:"In a formal discussion, 'Je me permettrais de nuancer' signals:",opts:["a polite partial disagreement","an enthusiastic agreement","a request for a short break","a change of topic"],a:0,ex:"Nuancer with the conditionnel is a courteous way to introduce an objection without confrontation."}]},
    {t:"Review: nuance",s:"Review",qs:[
      {q:"Which expression limits a claim to 'up to a point'?",opts:["dans une certaine mesure","sans aucune mesure","sur mesure","outre mesure"],a:0,ex:"Dans une certaine mesure = to some extent; sur mesure means tailor-made and outre mesure means excessively."},
      {q:"'Il a quasiment terminé' means he has:",opts:["almost finished","barely started","just finished","finished early"],a:0,ex:"Quasiment = practically / almost, so the work is not quite done yet."},
      {q:"Which sentence uses mise en relief correctly?",opts:["C'est pour cette raison que j'ai refusé.","C'est pour cette raison qui j'ai refusé.","C'est pour cette raison dont j'ai refusé.","C'est pour cette raison où j'ai refusé."],a:0,ex:"A highlighted complement (pour cette raison) is followed by que, not qui, dont or où."}]},
    {t:"Challenge: shades of certainty",s:"Challenge",qs:[
      {q:"Which sentence expresses the most doubt?",opts:["Je doute qu'il soit au courant.","Je pense qu'il est au courant.","Je sais qu'il est au courant.","Je suis sûr qu'il est au courant."],a:0,ex:"Douter que plus the subjunctive marks doubt; penser, savoir and être sûr take the indicative."},
      {q:"'Il n'est pas exclu que...' introduces:",opts:["a possibility, with the subjunctive","a certainty, with the indicative","an impossibility, with the future","an order, with the imperative"],a:0,ex:"Il n'est pas exclu que = it can't be ruled out that; as an expression of possibility it takes the subjunctive."},
      {q:"Fill the gap: 'un ___ accident' — the speaker suspects it was no accident.",opts:["prétendu","véritable","malheureux","grave"],a:0,ex:"Placed before the noun, prétendu signals that the speaker rejects the label 'accident'."}]}
  ],
  // Module 2: Academic Reading & Precision
  [
    {t:"Academic key terms",s:"Vocabulary",qs:[
      {q:"'il en découle que' means:",opts:["it follows that","it seems that","it is said that","it is doubtful that"],a:0,ex:"Découler de = to result from; il en découle que draws a logical consequence."},
      {q:"In a French dissertation, the 'antithèse' is:",opts:["the part arguing against the thesis","the final summary of ideas","the list of sources used","the opening paragraph"],a:0,ex:"French essays often follow thèse - antithèse - synthèse; the antithèse presents the opposing view."},
      {q:"'le présent travail' in an article means:",opts:["this very paper","the author's job","a previous paper","an ongoing survey"],a:0,ex:"In academic French, présent(e) before the noun means 'this' document being presented."}]},
    {t:"Precise connectors",s:"Vocabulary",qs:[
      {q:"'susmentionné' means:",opts:["above-mentioned","underlined","mentioned below","unmentioned"],a:0,ex:"Sus- means above (as in susdit); for something below, French says ci-dessous."},
      {q:"'à l'instar de' means:",opts:["like / following the example of","unlike / in contrast to","instead of / in place of","at the request of"],a:0,ex:"À l'instar de compares with a model: à l'instar de Durkheim = like Durkheim."},
      {q:"Odd one out: which connector does NOT express consequence?",opts:["or","ainsi","dès lors","par conséquent"],a:0,ex:"Or introduces a new premise (now / yet); ainsi, dès lors and par conséquent draw consequences."}]},
    {t:"Academic sounds",s:"Pronunciation",qs:[
      {q:"Listen. In 'susmentionné', how is the first syllable 'sus' pronounced?",say:"l'étude susmentionnée",opts:["[sys], with the s sounded","[sy], with a silent s","[sus], like English 'soos'","[zys], with a z sound"],a:0,ex:"Unlike the silent s of sous, the s in sus- is pronounced: [sys-mɑ̃-sjɔ-ne]."},
      {q:"Listen. In 'thèse', how is 'th' pronounced?",say:"la thèse et l'antithèse",opts:["like t","like English th","like s","like f"],a:0,ex:"French th is always a plain t sound; the s between vowels in thèse sounds like z."},
      {q:"Listen. How many syllables does 'découle' have in normal speech?",say:"Il en découle que",opts:["two","three","one","four"],a:0,ex:"The final -e of découle is silent in normal speech, so it is dé-coule: two syllables."}]},
    {t:"The subjunctive in academic prose",s:"Grammar",qs:[
      {q:"'Il est indispensable que chaque source ___ citée.'",opts:["soit","est","sera","serait"],a:0,ex:"Il est indispensable que expresses necessity and therefore requires the subjunctive."},
      {q:"'Bien que l'échantillon ___ réduit, les résultats sont fiables.'",opts:["soit","est","était","sera"],a:0,ex:"Bien que (although) expresses concession and always takes the subjunctive."},
      {q:"'Je regrette que l'auteur ne ___ aucune référence.'",opts:["fasse","fait","fera","faisait"],a:0,ex:"Regretter que expresses emotion, which triggers the subjunctive (fasse)."}]},
    {t:"Indicative or subjunctive?",s:"Grammar",qs:[
      {q:"Complete: 'Le colloque est annulé ___ grèves.'",opts:["en raison des","en raison de les","parce que les","à cause que les"],a:0,ex:"En raison de is followed by a noun, and de + les contracts to des."},
      {q:"Nominal style for 'Les chercheurs ont analysé les données':",opts:["l'analyse des données","l'analysement des données","les données analysantes","l'analysation des données"],a:0,ex:"The noun from analyser is l'analyse; nominal style turns the verb into a noun phrase."},
      {q:"Which sentence is correct after an expression of certainty?",opts:["Il est clair que l'hypothèse est fausse.","Il est clair que l'hypothèse soit fausse.","Il est clair que l'hypothèse fût fausse.","Il est clair que l'hypothèse être fausse."],a:0,ex:"Expressions of certainty take the indicative; the subjunctive is for necessity, doubt or emotion."}]},
    {t:"Reading: an abstract",s:"Reading",qs:[
      {q:"Read: 'La présente étude porte sur 300 étudiants. Or, l'échantillon ne comprend aucun étudiant étranger.' What does 'Or' introduce?",opts:["a limitation of the study","a second, separate study","the final conclusion","an illustrative example"],a:0,ex:"Or introduces a fact that shifts the reasoning, here a weakness in the sample."},
      {q:"Read: 'À l'instar de Bourdieu, l'auteure analyse l'école comme un lieu de reproduction sociale.' What does she do?",opts:["She follows Bourdieu's approach.","She criticises Bourdieu's approach.","She ignores Bourdieu completely.","She reviews Bourdieu's life."],a:0,ex:"À l'instar de means following the example of: she adopts Bourdieu's view."},
      {q:"Read: 'Les données susmentionnées sont incomplètes ; dès lors, toute conclusion reste provisoire.' Which is true?",opts:["The conclusions are only tentative.","The data are complete and final.","New data will be listed below.","The conclusions are definitive."],a:0,ex:"Susmentionnées refers back to data already given, and dès lors draws the consequence: conclusions stay provisional."}]},
    {t:"Listening: a research talk",s:"Listening",qs:[
      {q:"Listen. What happens to the initial hypothesis?",say:"Il en découle que l'hypothèse initiale doit être abandonnée.",opts:["It must be abandoned.","It is confirmed.","It must be tested again.","It is partly correct."],a:0,ex:"Il en découle que introduces the logical result: the hypothesis has to be dropped."},
      {q:"Listen. Why was the survey conducted online?",say:"Du fait de la pandémie, l'enquête a été menée en ligne.",opts:["because of the pandemic","because it was cheaper","because of a strike","to reach more people"],a:0,ex:"Du fait de = because of / owing to, and like en raison de it is followed by a noun."},
      {q:"Listen. What do the results do?",say:"En effet, les résultats confirment notre thèse.",opts:["They confirm the thesis.","They contradict the thesis.","They are not yet known.","They raise new questions."],a:0,ex:"En effet confirms what came before, and confirment states that the data support the thesis."}]},
    {t:"Presenting research",s:"Speaking",qs:[
      {q:"Presenting an abstract, you state the paper's aim. You say:",opts:["Le présent travail vise à analyser...","Le travail présent a pour viser...","Ce travail ici, il va regarder un peu...","Ce papier, en gros, il analyse..."],a:0,ex:"Le présent travail vise à + infinitive is the standard formal way to announce an aim."},
      {q:"Reporting a researcher's claim without endorsing it, you say:",opts:["Selon l'auteure, le phénomène serait récent.","L'auteure a raison, le phénomène est récent.","Je pense que le phénomène est récent.","L'auteure se trompe sur ce phénomène."],a:0,ex:"Selon + conditionnel attributes the claim to the author without taking a position."},
      {q:"Someone asks why your sample was small. Which answer is precise and academic?",opts:["En raison de contraintes budgétaires, nous avons limité l'échantillon.","Bah, on n'avait pas vraiment assez d'argent pour faire plus, du coup.","Parce que c'était comme ça et qu'on ne pouvait pas faire autrement.","On a fait avec ce qu'on avait sous la main, voilà tout, quoi."],a:0,ex:"En raison de + noun names the cause precisely, and nous fits academic register; the others are casual."}]},
    {t:"Writing an academic summary",s:"Writing",qs:[
      {q:"Choose the correct sentence for a methods section.",opts:["Il faut que les sources soient vérifiées.","Il faut que les sources sont vérifiées.","Il faut que les sources soit vérifiées.","Il faut que les sources sont vérifiés."],a:0,ex:"Il faut que takes the subjunctive, and soient vérifiées agrees with the feminine plural sources."},
      {q:"Fill the gap: '___ étude examine l'effet du télétravail sur la productivité.'",opts:["La présente","Le présent","La présentée","Présentement"],a:0,ex:"Étude is feminine, so la présente étude; présentée would mean 'introduced' or 'shown'."},
      {q:"Choose the correct form: 'les résultats ___' (above-mentioned)",opts:["susmentionnés","sus-mentionnées","susmentionées","susmentionné"],a:0,ex:"Susmentionné is one word with double n and agrees with résultats (masculine plural)."}]},
    {t:"French academic conventions",s:"Culture",qs:[
      {q:"Which pronoun do French academics traditionally use even when writing alone?",opts:["nous","je","tu","vous"],a:0,ex:"The 'nous de modestie' avoids a self-centred je in academic texts, even for a single author."},
      {q:"The classic plan of a French 'dissertation' is:",opts:["thèse, antithèse, synthèse","introduction, data, discussion","problem, solution, result","hook, story, moral"],a:0,ex:"This dialectical three-part plan is taught in French schools and still shapes academic argument."},
      {q:"Before a colon, semicolon, '?' or '!', French typography puts:",opts:["a space","no space","a hyphen","a dash"],a:0,ex:"French uses a (non-breaking) space before two-part punctuation marks, unlike English."}]},
    {t:"Review: academic French",s:"Review",qs:[
      {q:"The opposing position to 'la thèse' in a dissertation is:",opts:["l'antithèse","la synthèse","l'hypothèse","la parenthèse"],a:0,ex:"The antithèse argues against the thesis; the synthèse then reconciles or goes beyond both."},
      {q:"'Nous ne pensons pas que cette méthode ___ adaptée.'",opts:["soit","est","sera","était"],a:0,ex:"Negated penser que expresses doubt and takes the subjunctive."},
      {q:"Which connector fits: 'Le corpus est vaste ; ___, l'analyse reste partielle.'",opts:["toutefois","en effet","ainsi","dès lors"],a:0,ex:"Toutefois (however) marks the contrast; the others would wrongly suggest confirmation or consequence."}]},
    {t:"Challenge: precise argument",s:"Challenge",qs:[
      {q:"'Quoi que l'on ___, les chiffres restent préoccupants.'",opts:["fasse","fait","fera","ferait"],a:0,ex:"Quoi que (whatever) is a concessive expression that requires the subjunctive."},
      {q:"Which sentence uses 'or' correctly as a logical connector?",opts:["Tous les métaux conduisent l'électricité. Or, le cuivre est un métal.","Le cuivre est un métal, or bien il conduit l'électricité.","Or que le cuivre soit un métal, il conduit l'électricité.","Le cuivre conduit l'électricité, or alors c'est un métal."],a:0,ex:"Or introduces the second premise of an argument, usually at the start of a sentence followed by a comma."},
      {q:"'Il est peu probable que l'étude ___ reproduite.'",opts:["soit","est","sera","a été"],a:0,ex:"Il est probable que takes the indicative, but peu probable expresses doubt and needs the subjunctive."}]}
  ],
  // Module 3: Idioms & Stylistic Choice
  [
    {t:"Everyday idioms",s:"Vocabulary",qs:[
      {q:"'tomber dans les pommes' means:",opts:["to faint","to fall in love","to get lucky","to get lost"],a:0,ex:"Despite the apples, tomber dans les pommes simply means to pass out."},
      {q:"Complete the idiom for something very expensive: 'Ce sac coûte ___.'",opts:["les yeux de la tête","la mer à boire","un poil dans la main","le cafard"],a:0,ex:"Coûter les yeux de la tête is the fixed idiom for 'to cost an arm and a leg'."},
      {q:"Your friend never showed up for your date. You say: 'Il m'a ___.'",opts:["posé un lapin","donné sa langue au chat","coûté les yeux","fait la tête"],a:0,ex:"Poser un lapin à quelqu'un = to stand someone up; faire la tête means to sulk."}]},
    {t:"More idioms and style terms",s:"Vocabulary",qs:[
      {q:"'donner sa langue au chat' means:",opts:["to give up guessing","to stay silent from fear","to talk far too much","to reveal a secret"],a:0,ex:"It is said when you can't find the answer to a riddle and ask to be told."},
      {q:"Which idiom means 'to feel down'?",opts:["avoir le cafard","avoir la pêche","avoir la frite","avoir du pot"],a:0,ex:"Avoir le cafard = to have the blues; la pêche and la frite mean full of energy, avoir du pot means lucky."},
      {q:"In stylistics, 'la mise en relief' means:",opts:["emphasis","a summary","a digression","an exaggeration"],a:0,ex:"Mettre en relief = to make something stand out, e.g. with c'est ... que or dislocation."}]},
    {t:"Idioms out loud",s:"Pronunciation",qs:[
      {q:"Listen. Which nasal vowel do you hear at the end of 'lapin'?",say:"Il m'a posé un lapin.",opts:["[ɛ̃] as in 'vin'","[ɑ̃] as in 'vent'","[ɔ̃] as in 'vont'","[a] as in 'va'"],a:0,ex:"The spelling -in is pronounced [ɛ̃], the same nasal vowel as in vin and pain."},
      {q:"Listen. What links 'les' and 'yeux'?",say:"les yeux de la tête",opts:["a z sound (liaison)","nothing, they are separate","a t sound","an n sound"],a:0,ex:"Les + yeux is a compulsory liaison: [le-zjø]."},
      {q:"Listen. How is 'pommes' pronounced?",say:"tomber dans les pommes",opts:["[pɔm], one syllable","[pɔ-me], two syllables","[pɔmz], with a final z","[pɔ̃m], with a nasal o"],a:0,ex:"The double m keeps the vowel oral, and the final -es is silent: one syllable."}]},
    {t:"Mise en relief and dislocation",s:"Grammar",qs:[
      {q:"Highlight the object: 'J'ai lu ce livre.' →",opts:["C'est ce livre que j'ai lu.","C'est ce livre qui j'ai lu.","C'est ce livre dont j'ai lu.","Ce livre, c'est qui j'ai lu."],a:0,ex:"When the highlighted element is the object, c'est ... que is used."},
      {q:"Which sentence uses dislocation (a detached element picked up by a pronoun)?",opts:["Ce film, je l'ai adoré.","J'ai adoré ce film.","C'est un film adoré.","J'adore les films."],a:0,ex:"Ce film is moved to the front and repeated by the pronoun l', a typical spoken way to emphasise."},
      {q:"Highlight the date: 'Elle a compris en 2010.' →",opts:["C'est en 2010 qu'elle a compris.","C'est en 2010 où elle a compris.","C'est en 2010 qui elle a compris.","C'est 2010 quand elle a compris."],a:0,ex:"Standard mise en relief of a time expression uses c'est ... que; c'est ... où is considered incorrect."}]},
    {t:"Emphasis: tricky cases",s:"Grammar",qs:[
      {q:"'Ce sont eux qui ___ gagné.'",opts:["ont","a","avons","est"],a:0,ex:"After ce sont eux qui, the verb agrees with eux (third person plural): ont."},
      {q:"'Ce qui me plaît, ___ son humour.'",opts:["c'est","ce sont","il est","est"],a:0,ex:"In the pseudo-cleft ce qui ..., c'est ..., the highlighted element is introduced by c'est."},
      {q:"Which sentence is correct?",opts:["C'est de ce projet que je vous ai parlé.","C'est ce projet dont je vous ai parlé de.","C'est de ce projet dont je vous ai parlé.","C'est ce projet que je vous ai parlé."],a:0,ex:"With parler de, say c'est de ce projet que or c'est ce projet dont; combining de and dont repeats the preposition."}]},
    {t:"Reading: style and idiom",s:"Reading",qs:[
      {q:"Read: 'Le déménagement ? Franchement, ce n'était pas la mer à boire.' How did the move go?",opts:["It was manageable.","It was exhausting.","It was cancelled.","It was very far."],a:0,ex:"Ce n'est pas la mer à boire means a task is not that difficult."},
      {q:"Read: 'Il pleuvait. Le train ne venait pas. Elle attendait.' What effect does the style create?",opts:["a tense, halting rhythm","a long, flowing rhythm","a comic, playful tone","a formal, legal tone"],a:0,ex:"Parataxe - short clauses set side by side without links - creates an abrupt, tense rhythm."},
      {q:"Read: 'Après l'audition, Paul est tombé dans les pommes ; on a dû appeler les secours.' What happened to Paul?",opts:["He fainted.","He failed.","He fell over.","He celebrated."],a:0,ex:"Tomber dans les pommes = to faint, which is why the emergency services were called."}]},
    {t:"Listening: idioms in context",s:"Listening",qs:[
      {q:"Listen. What happened?",say:"Je l'ai attendu une heure devant le cinéma, et il m'a posé un lapin.",opts:["The other person never came.","The other person came late.","They watched a film together.","He brought the speaker a gift."],a:0,ex:"Poser un lapin = to stand someone up: the speaker waited an hour for nothing."},
      {q:"Listen. How does the speaker feel?",say:"Depuis son départ, j'ai un peu le cafard.",opts:["a bit low","very angry","relieved","excited"],a:0,ex:"Avoir le cafard = to feel down; un peu softens it to 'a bit low'."},
      {q:"Listen. What annoys the speaker?",say:"Ce qui m'agace, c'est son arrogance.",opts:["the person's arrogance","the person's lateness","the person's noise","the person's silence"],a:0,ex:"The structure ce qui ..., c'est ... places son arrogance in focus at the end."}]},
    {t:"Choosing the right register",s:"Speaking",qs:[
      {q:"A friend is stressed about a simple form. To reassure them informally, you say:",opts:["T'inquiète, ce n'est pas la mer à boire !","T'inquiète, tu coûtes les yeux de la tête !","T'inquiète, tu vas tomber dans les pommes !","T'inquiète, tu m'as posé un lapin !"],a:0,ex:"Ce n'est pas la mer à boire reassures: the task is not hard. The other idioms don't fit the situation."},
      {q:"In a job interview you are asked how you handle setbacks. Which reply has the right register?",opts:["Je prends du recul et j'analyse la situation.","Bof, quand ça foire, je m'en fiche un peu.","J'ai le cafard et je laisse tomber, quoi.","Ça me gonfle, alors je passe à autre chose."],a:0,ex:"An interview needs neutral-formal French; foirer, se ficher, gonfler and quoi are familiar."},
      {q:"You want to stress that YOU paid, not your brother. You say:",opts:["C'est moi qui ai payé, pas mon frère.","J'ai payé, moi aussi, avec mon frère.","Mon frère, il a payé pour moi.","Moi, j'ai été payé par mon frère."],a:0,ex:"C'est moi qui ai payé singles out the speaker as the one who paid."}]},
    {t:"Writing idioms correctly",s:"Writing",qs:[
      {q:"Choose the correctly written idiom.",opts:["Ça coûte les yeux de la tête.","Ça coûte l'œil de la tête.","Ça coûte des yeux de la tête.","Ça coûte les yeux de sa tête."],a:0,ex:"Idioms are fixed: only 'les yeux de la tête' is used; changing an article breaks the expression."},
      {q:"Rewrite in a neutral, formal style: 'Il est tombé dans les pommes.'",opts:["Il a perdu connaissance.","Il a perdu la tête.","Il est tombé malade.","Il a perdu l'équilibre."],a:0,ex:"Perdre connaissance is the neutral equivalent; perdre la tête means to lose one's mind."},
      {q:"Fill the gap: 'Ce sont les candidates ___ ont été retenues.'",opts:["qui","que","qu'","dont"],a:0,ex:"The highlighted candidates are the subject of ont été retenues, so qui is needed."}]},
    {t:"Idioms and French culture",s:"Culture",qs:[
      {q:"Which expression would be out of place in a formal report?",opts:["C'est la galère.","Il convient de noter...","Force est de constater...","Il va sans dire..."],a:0,ex:"La galère is informal slang for a nightmare; the others are formal set phrases."},
      {q:"Chimène's 'Va, je ne te hais point' (Corneille, Le Cid) is a famous litote. It means:",opts:["I love you","I hate you","leave me alone","I forgive you"],a:0,ex:"A litote says less to suggest more: 'I do not hate you' implies 'I love you'."},
      {q:"The French equivalent of 'to have a frog in your throat' is:",opts:["avoir un chat dans la gorge","avoir une grenouille dans la gorge","avoir un lapin dans la gorge","avoir un poisson dans la gorge"],a:0,ex:"French idioms often use different animals: the English frog becomes a French cat."}]},
    {t:"Review: idioms and style",s:"Review",qs:[
      {q:"'avoir la pêche' means:",opts:["to be full of energy","to be feeling sad","to go out fishing","to be very lucky"],a:0,ex:"Avoir la pêche (literally 'to have the peach') means to be in great shape; la pêche also means fishing."},
      {q:"Which sentence is an example of hypotaxe?",opts:["Bien qu'il fût fatigué, il continua, car il voulait finir.","Il était fatigué. Il continua quand même. Il voulait finir.","Fatigué, toujours fatigué, et pourtant il continua.","Il continua, fatigué, sans cesse, sans repos."],a:0,ex:"Hypotaxe links ideas through subordination (bien que, car); the others juxtapose or coordinate."},
      {q:"Fill the gap: 'Hier, j'avais ___, je suis resté au lit toute la journée.'",opts:["le cafard","la pêche","un lapin","la mer"],a:0,ex:"Avoir le cafard (to feel low) explains staying in bed all day."}]},
    {t:"Challenge: idiom and style",s:"Challenge",qs:[
      {q:"'Il ne faut pas vendre la peau de l'ours avant de l'avoir tué' means:",opts:["don't count your chickens before they hatch","never trust a hunter's promises","don't sell what you still need","act before it is too late"],a:0,ex:"The proverb warns against celebrating success before it is certain."},
      {q:"Which sentence is NOT correct French?",opts:["C'est à toi à qui je parle.","C'est à toi que je parle.","C'est toi à qui je parle.","C'est toi qui me parles."],a:0,ex:"C'est à toi à qui repeats the preposition à; use c'est à toi que or c'est toi à qui."},
      {q:"Rewrite in literary hypotaxe: 'Il était tard. Elle ne dormait pas.'",opts:["Bien qu'il fût tard, elle ne dormait pas.","Il était tard, elle ne dormait pas.","Il était tard. Et elle ne dormait pas.","Tard, elle ne dormait toujours pas."],a:0,ex:"Bien que subordinates the first idea, with the literary imperfect subjunctive fût; the others only juxtapose."}]}
  ],
  // Module 4: Long-form Listening & Summary
  [
    {t:"Lecture vocabulary",s:"Vocabulary",qs:[
      {q:"At a university, 'une conférence' is usually:",opts:["a lecture or talk","a phone call","a meeting room","a written exam"],a:0,ex:"Une conférence is a public talk or lecture; a large professional gathering is often un congrès or un colloque."},
      {q:"'l'idée maîtresse' means:",opts:["the main idea","the teacher's idea","a clever idea","the first idea"],a:0,ex:"Maître / maîtresse here means principal: the central idea that organises a talk."},
      {q:"'en somme' means:",opts:["in short","by the way","in addition","for instance"],a:0,ex:"En somme sums up the essence of what has been said, like en bref."}]},
    {t:"Summarising phrases",s:"Vocabulary",qs:[
      {q:"'remettre en question' means:",opts:["to question / challenge","to ask the same again","to postpone a decision","to answer a question"],a:0,ex:"Remettre en question = to call into doubt; asking again would be reposer la question."},
      {q:"'en substance' means:",opts:["in essence","in material form","in great detail","in passing"],a:0,ex:"En substance introduces the core content of a message without the details."},
      {q:"Which expression means 'to take notes'?",opts:["prendre des notes","faire des notes","tenir des notes","donner des notes"],a:0,ex:"The fixed collocation is prendre des notes; donner des notes means to give marks."}]},
    {t:"Linking and silent letters",s:"Pronunciation",qs:[
      {q:"Listen. How is 'était' pronounced?",say:"Il était déjà parti.",opts:["[e-tɛ], final t silent","[e-tɛt], final t sounded","[e-ta], like 'état' with a","[ɛ-ti], ending in i"],a:0,ex:"The -ait ending sounds [ɛ] and the final t is silent (except in liaison before a vowel)."},
      {q:"Listen. How does 'en somme' sound?",say:"en somme",opts:["[ɑ̃ sɔm]","[ɑ̃n sɔm]","[ɛn sɔm]","[ɑ̃ sɔ-me]"],a:0,ex:"En is a nasal vowel with no n sound before a consonant, and the final -e of somme is silent."},
      {q:"Listen. Which syllable of 'conséquent' is stressed?",say:"par conséquent",opts:["-quent, the last","con-, the first","-sé-, the middle","the first two equally"],a:0,ex:"French stress falls on the last syllable of the rhythm group: par conséquent ends on -quent."}]},
    {t:"The plus-que-parfait",s:"Grammar",qs:[
      {q:"'Il ___ déjà ___ la salle quand la conférence a commencé.'",opts:["avait / quitté","a / quitté","aura / quitté","avais / quitté"],a:0,ex:"Leaving came before the start of the lecture, so it takes the plus-que-parfait: il avait quitté."},
      {q:"Plus-que-parfait of 'elle arrive':",opts:["elle était arrivée","elle avait arrivé","elle est arrivée","elle était arrivé"],a:0,ex:"Arriver takes être, and the participle agrees with elle: était arrivée."},
      {q:"'Le conférencier a repris l'argument qu'il ___ la veille.'",opts:["avait présenté","a présenté","présentait","présentera"],a:0,ex:"The presentation happened the day before the other past action, so it is in the plus-que-parfait."}]},
    {t:"Past sequences and reporting",s:"Grammar",qs:[
      {q:"'Les notes qu'elle ___ prises étaient précieuses.'",opts:["avait","était","avaient","étaient"],a:0,ex:"Prendre takes avoir; the participle prises agrees with the preceding object que (les notes)."},
      {q:"Which reporting verb is neutral (no evaluation) in a compte rendu?",opts:["L'auteur indique que...","L'auteur prétend que...","L'auteur s'imagine que...","L'auteur ose affirmer que..."],a:0,ex:"Indiquer is neutral; prétendre and s'imaginer suggest doubt, and ose affirmer adds judgement."},
      {q:"'Quand nous sommes arrivés, l'orateur ___ son introduction.'",opts:["avait déjà terminé","a déjà terminé","termine déjà","terminera déjà"],a:0,ex:"The introduction was finished before we arrived, so the plus-que-parfait marks the earlier event."}]},
    {t:"Reading: a synthèse",s:"Reading",qs:[
      {q:"Read: 'D'une part, le télétravail réduit les trajets ; d'autre part, il isole les salariés. En somme, son bilan est contrasté.' What is the conclusion?",opts:["The overall picture is mixed.","Remote work is clearly positive.","Remote work is clearly negative.","No conclusion is drawn."],a:0,ex:"D'une part / d'autre part balance two aspects, and en somme concludes that the result is contrasté (mixed)."},
      {q:"Read: 'L'intervenante remet en question l'idée selon laquelle la croissance serait illimitée.' What does she do?",opts:["She challenges the idea.","She supports the idea.","She repeats the question.","She ignores the idea."],a:0,ex:"Remettre en question = to challenge; the conditionnel serait also distances her from the idea."},
      {q:"Read: 'Ce texte est remarquable et l'auteur a parfaitement raison.' Why is this unsuitable in a compte rendu?",opts:["It gives a personal judgement.","It is too short to be useful.","It is written in the present.","It mentions the author."],a:0,ex:"A compte rendu reports content neutrally; remarquable and a parfaitement raison are evaluations."}]},
    {t:"Listening: a long talk",s:"Listening",qs:[
      {q:"Listen. In essence, what is the speaker's main point?",say:"En substance, l'orateur affirme que l'école doit s'adapter au numérique.",opts:["School must adapt to digital technology.","Digital technology harms schools.","Schools should ban screens.","Teachers need higher salaries."],a:0,ex:"En substance introduces the core claim: l'école doit s'adapter au numérique."},
      {q:"Listen. Which happened first?",say:"Quand j'ai allumé la radio, l'émission avait déjà commencé.",opts:["The programme started.","The speaker turned on the radio.","Both at the same moment.","The programme ended."],a:0,ex:"Avait commencé (plus-que-parfait) marks the earlier event: the programme had already started."},
      {q:"Listen. What will have to happen?",say:"Par conséquent, il faudra revoir l'ensemble du projet.",opts:["The whole project must be reviewed.","The project will be cancelled.","The project is now finished.","Only one part will change."],a:0,ex:"Par conséquent introduces the result, and l'ensemble du projet means the project as a whole."}]},
    {t:"Summing up aloud",s:"Speaking",qs:[
      {q:"You must summarise a podcast in one sentence. You begin:",opts:["En substance, l'intervenant soutient que...","Moi, j'ai trouvé que c'était trop bien...","Alors, au début, il dit bonjour, puis...","Franchement, je n'ai rien compris, mais..."],a:0,ex:"En substance + a neutral reporting verb (soutient que) goes straight to the core claim."},
      {q:"After a neutral summary, you move to your own critique. You say:",opts:["Pour ma part, je nuancerais cette analyse.","L'intervenant indique ensuite que...","En substance, le podcast explique que...","D'après l'auteur, la question serait..."],a:0,ex:"Pour ma part signals your personal view and separates the critique from the summary."},
      {q:"You missed a point in a lecture. You politely ask the lecturer:",opts:["Pourriez-vous revenir sur votre deuxième point ?","Hein ? Vous avez dit quoi, là, au juste ?","Répétez, j'ai pas suivi votre truc, là.","C'était quoi, le deuxième machin, déjà ?"],a:0,ex:"Pourriez-vous (conditionnel) + revenir sur is polite and precise; the others are familiar."}]},
    {t:"Writing a synthèse",s:"Writing",qs:[
      {q:"Choose the correct plus-que-parfait sentence.",opts:["Elles étaient parties avant la fin.","Elles avaient parties avant la fin.","Elles étaient parti avant la fin.","Elles avaient partis avant la fin."],a:0,ex:"Partir takes être, so the participle agrees with elles: étaient parties."},
      {q:"Fill the gap: 'Les deux documents abordent la même question ; ___, leurs conclusions divergent.'",opts:["en revanche","par conséquent","en effet","ainsi"],a:0,ex:"En revanche marks the contrast between the shared question and the diverging conclusions."},
      {q:"Best opening sentence for a synthèse:",opts:["Les trois documents s'interrogent sur l'avenir du travail.","J'ai vraiment adoré lire ces trois documents sur le travail.","Je vais maintenant vous parler un peu de ces documents.","À mon avis, ces documents sur le travail sont plutôt nuls."],a:0,ex:"A synthèse opens by presenting the documents' common theme neutrally, without opinion."}]},
    {t:"Lectures and podcasts in France",s:"Culture",qs:[
      {q:"France Culture is:",opts:["a public talk radio station","a cultural newspaper","a film TV channel","a private music station"],a:0,ex:"France Culture, part of Radio France, broadcasts lectures, debates and documentaries - ideal long-form listening."},
      {q:"In the French 'note de synthèse' exercise, the writer must:",opts:["combine the documents objectively, without opinion","give a personal opinion on each document","copy out the key sentences of every text","rank the documents from best to worst"],a:0,ex:"A note de synthèse confronts and organises the documents' ideas while staying strictly objective."},
      {q:"The Collège de France is known for:",opts:["free lectures open to everyone","a very selective entrance exam","awarding doctoral diplomas","training senior civil servants"],a:0,ex:"Its courses are free, open to all, award no diplomas, and many are available as podcasts."}]},
    {t:"Review: listening and summary",s:"Review",qs:[
      {q:"'Il avait plu toute la nuit' expresses:",opts:["an earlier past event","a future event","a present habit","a hypothesis"],a:0,ex:"The plus-que-parfait (avait plu) places the rain before another past moment."},
      {q:"Which marker announces the final conclusion of a talk?",opts:["en définitive","d'une part","par exemple","tout d'abord"],a:0,ex:"En définitive = ultimately; d'une part and tout d'abord open a list, par exemple illustrates."},
      {q:"Which verb fits a neutral summary: 'La conférencière ___ trois causes principales.'",opts:["distingue","imagine","prétend","exagère"],a:0,ex:"Distinguer reports neutrally; imagine, prétend and exagère carry a judgement about the speaker."}]},
    {t:"Challenge: faithful summaries",s:"Challenge",qs:[
      {q:"Which sentence correctly orders two past events?",opts:["Il a relu les notes qu'il avait prises la veille.","Il a relu les notes qu'il prendra la veille.","Il avait relu les notes qu'il a prises la veille.","Il relit les notes qu'il avait pris la veille."],a:0,ex:"Taking notes came first (avait prises), rereading came later (a relu); prises agrees with notes."},
      {q:"Which is a faithful, neutral summary of 'Le gouvernement aurait sous-estimé la crise, selon plusieurs experts.'?",opts:["Plusieurs experts estiment que la crise a été sous-estimée.","Le gouvernement a sous-estimé la crise, c'est un fait.","La crise a été très bien gérée par le gouvernement.","Je pense que le gouvernement a mal agi dans la crise."],a:0,ex:"The original attributes the claim to experts; a faithful summary keeps that attribution and adds no opinion."},
      {q:"In a long talk, 'Revenons-en à notre fil conducteur' means the speaker:",opts:["returns to the main thread after a digression","starts a completely new and unrelated topic","concludes the whole talk immediately","asks the audience a direct question"],a:0,ex:"Le fil conducteur is the main thread; revenons-en signals a return to it after a detour."}]}
  ],
  // Module 5: Formal Writing, Speaking & Editing
  [
    {t:"Formal letter formulas",s:"Vocabulary",qs:[
      {q:"'Je vous saurais gré de me répondre' means:",opts:["I would be grateful if you replied","I know that you will reply","I thank you for replying","I demand that you reply"],a:0,ex:"Savoir gré de = to be grateful for; the conditionnel saurais makes the request polite."},
      {q:"'dans les plus brefs délais' means:",opts:["as soon as possible","within the legal deadline","in a few words","at the latest"],a:0,ex:"Les plus brefs délais = the shortest possible time; it is a firm but formal request for speed."},
      {q:"'Suite à votre courrier du 3 mars' means:",opts:["Further to your letter of 3 March","Following your visit on 3 March","Before your letter of 3 March","Unlike your email of 3 March"],a:0,ex:"Suite à = following / further to, and un courrier is a letter."}]},
    {t:"Editing and spontaneous speech",s:"Vocabulary",qs:[
      {q:"'peaufiner un texte' means:",opts:["to polish a text","to shorten a text","to translate a text","to sign a text"],a:0,ex:"Peaufiner = to put the finishing touches to something, as in a final editing pass."},
      {q:"'À brûle-pourpoint, je dirais...' introduces:",opts:["an off-the-cuff answer","a carefully prepared answer","a burning complaint","a written quotation"],a:0,ex:"À brûle-pourpoint = point-blank / without preparation; it signals spontaneous speech."},
      {q:"The opposite of 'peaufiner' (to polish) is:",opts:["bâcler","fignoler","parfaire","soigner"],a:0,ex:"Bâcler means to botch or rush; fignoler, parfaire and soigner are all close to peaufiner."}]},
    {t:"Formal sounds",s:"Pronunciation",qs:[
      {q:"Listen. How is 'Monsieur' pronounced?",say:"Veuillez agréer, Madame, Monsieur...",opts:["[mə-sjø]","[mɔ̃-sjœʁ]","[mɔn-sjø]","[mɔ̃-si-œʁ]"],a:0,ex:"Monsieur is irregular: the first syllable is a weak [mə] and the final r is silent."},
      {q:"Listen. Which sound does 'veuillez' begin with?",say:"veuillez",opts:["[vœj], as in 'feuille'","[vwi], as in 'oui'","[vɛl], with an l","[vøl], with an l"],a:0,ex:"The spelling -euill- gives [œj], as in feuille; the double l is not pronounced as l."},
      {q:"Listen. In 'ci-joint', the final t is:",say:"Veuillez trouver ci-joint mon dossier.",opts:["silent","pronounced t","pronounced d","linked with z"],a:0,ex:"Final -t is silent in joint: [si-ʒwɛ̃], with the nasal [ɛ̃] as in point."}]},
    {t:"Formal request structures",s:"Grammar",qs:[
      {q:"'Je vous saurais gré de bien vouloir ___ ma demande.'",opts:["examiner","examinez","examiné","d'examiner"],a:0,ex:"Bien vouloir is followed directly by an infinitive: bien vouloir examiner."},
      {q:"'Veuillez ___ ci-joint mon curriculum vitae.'",opts:["trouver","trouvez","trouvé","trouverez"],a:0,ex:"Veuillez is the imperative of vouloir and is followed by an infinitive."},
      {q:"Choose the correct agreement: 'Les pièces ___ prouvent mon paiement.'",opts:["ci-jointes","ci-joint","ci-joints","ci-jointe"],a:0,ex:"Placed after the noun, ci-joint agrees like an adjective: les pièces (fem. pl.) ci-jointes."}]},
    {t:"Editing typical errors",s:"Grammar",qs:[
      {q:"Which sentence is correct in a formal reminder?",opts:["Je me permets de vous rappeler notre accord.","Je me permets à vous rappeler notre accord.","Je me permet de vous rappeler notre accord.","Je me permets de vous rappelez notre accord."],a:0,ex:"Se permettre de + infinitive; with je the verb ends in -s (permets), and rappeler stays infinitive."},
      {q:"Editing: which version avoids spoken fillers?",opts:["Le colis n'est pas arrivé ; j'ai donc contacté le service.","Le colis n'est pas arrivé, du coup j'ai contacté le service.","En fait, le colis n'est pas arrivé, j'ai contacté le service.","Bon, le colis n'est pas arrivé, j'ai contacté le service."],a:0,ex:"Donc is a real logical connector; du coup, en fait and bon are spoken fillers to cut in formal writing."},
      {q:"Which sentence is correctly written for a complaint?",opts:["Je vous serais reconnaissant de me rembourser.","Je vous serait reconnaissant de me rembourser.","Je vous serais reconnaissant à me rembourser.","Je vous serais reconnaissant de me remboursez."],a:0,ex:"Je takes serais (conditionnel), être reconnaissant is followed by de, and rembourser stays infinitive."}]},
    {t:"Reading: formal letters",s:"Reading",qs:[
      {q:"Read: 'Suite à votre courrier du 12 mai, nous vous confirmons le remboursement dans les plus brefs délais.' What will happen?",opts:["You will be refunded very soon.","Your letter was lost on 12 May.","You must write again by 12 May.","Your refund has been refused."],a:0,ex:"Nous vous confirmons le remboursement + dans les plus brefs délais = the refund will come as soon as possible."},
      {q:"Read: 'Malgré mes relances, je n'ai reçu aucune réponse. Je vous saurais gré de régler ce litige.' What is the writer's purpose?",opts:["to ask for a dispute to be settled","to thank the company for its help","to cancel a previous complaint","to apply for a job at the company"],a:0,ex:"Un litige is a dispute, and je vous saurais gré de régler asks formally for it to be resolved."},
      {q:"Read the draft: 'En fait, du coup, j'ai pas reçu la facture, quoi.' What must change before it is sent formally?",opts:["remove the fillers and restore 'ne'","add more connectors like 'du coup'","switch to using 'tu'","make it even shorter"],a:0,ex:"Formal writing needs the full negation (je n'ai pas) and no fillers like en fait, du coup or quoi."}]},
    {t:"Listening: formal and spontaneous",s:"Listening",qs:[
      {q:"Listen. How precise is the figure?",say:"Grosso modo, le budget sera réduit d'un tiers.",opts:["approximate","exact to the euro","completely unknown","deliberately false"],a:0,ex:"Grosso modo = roughly, so 'a third' is an approximation."},
      {q:"Listen. How did the speaker answer?",say:"À brûle-pourpoint, je dirais que c'est une bonne idée, mais il faudrait y réfléchir.",opts:["spontaneously, with a reservation","after long, careful preparation","with a firm and final refusal","by quickly changing the subject"],a:0,ex:"À brûle-pourpoint marks an unprepared answer, and mais il faudrait y réfléchir adds a reservation."},
      {q:"Listen. What is being requested?",say:"Je vous prie de bien vouloir nous envoyer les documents avant vendredi.",opts:["the documents before Friday","a meeting late on Friday","a phone call after Friday","a full refund by Friday"],a:0,ex:"Je vous prie de bien vouloir is a formal request formula; the request is to send the documents."}]},
    {t:"Speaking without preparation",s:"Speaking",qs:[
      {q:"On an unprepared topic, you need a moment to think. You say:",opts:["C'est une question intéressante ; laissez-moi y réfléchir un instant.","Euh... je sais pas trop, moi, c'est quoi exactement la question ?","Aucune idée là-dessus, on passe à la question suivante ?","Bon, ben, du coup, voilà, en fait, je dirais que, euh..."],a:0,ex:"Acknowledging the question and asking for a moment buys time politely, without fillers."},
      {q:"You want to give an approximate figure in a meeting. You say:",opts:["Il s'agit, grosso modo, d'une centaine de clients.","Il s'agit exactement de cent clients précis.","Il s'agit, du coup, de clients, en fait.","Il s'agit de clients, je crois, ou pas."],a:0,ex:"Grosso modo hedges the number, and une centaine means 'about a hundred'."},
      {q:"You phone a company to chase a complaint politely. You say:",opts:["Je me permets de vous rappeler au sujet de ma réclamation.","Je vous rappelle encore une fois parce que vous ne faites rien.","Alors, ça avance ou pas, ma réclamation, là ?","Vous avez encore perdu mon dossier, c'est ça ?"],a:0,ex:"Je me permets de is a polite opener, and au sujet de ma réclamation states the purpose clearly."}]},
    {t:"Writing a formal letter",s:"Writing",qs:[
      {q:"Choose the correctly written closing formula.",opts:["Veuillez agréer, Madame, Monsieur, l'expression de mes salutations distinguées.","Veuillez agréez, Madame, Monsieur, l'expression de mes salutations distinguées.","Veuillez agréer, Madame, Monsieur, l'expression de mes salutation distinguées.","Veuillez agréer, Madame, Monsieur, l'expression de mes salutations distingués."],a:0,ex:"Agréer stays infinitive after veuillez, and salutations distinguées is feminine plural."},
      {q:"Fill the gap: '___ votre annonce parue le 2 juin, je souhaite poser ma candidature.'",opts:["Suite à","Suivant de","À la suite","Après de"],a:0,ex:"Suite à (or à la suite de) means following; the other forms are incomplete or ungrammatical."},
      {q:"Which subject line suits a formal complaint email?",opts:["Objet : Réclamation concernant la commande n° 4521","Objet : Gros problème avec ma commande, répondez vite !!!","Objet : Coucou, c'est encore moi pour ma commande","Objet : Vous m'avez arnaqué avec cette commande"],a:0,ex:"A formal subject line is factual: the type of letter (réclamation) and a reference number."}]},
    {t:"Letter-writing etiquette",s:"Culture",qs:[
      {q:"In a French formal letter, the opening 'Madame, Monsieur,' is followed by:",opts:["a comma, then a new line with a capital","a colon, then a lower-case word","an exclamation mark and a new line","a full stop on the same line"],a:0,ex:"French uses a comma after the salutation, and the body starts on a new line with a capital letter."},
      {q:"Why might 'Cordialement' alone be risky in a first letter to an authority?",opts:["It may seem too brief and casual","It is grammatically incorrect","It is only used between friends","It is rude in every context"],a:0,ex:"Cordialement is fine in everyday emails, but a formal first letter usually ends with a full formula."},
      {q:"In formal French writing, 'Monsieur le Directeur' is used to:",opts:["address the person by their title","mock the director politely","refer to a third person","sign the letter"],a:0,ex:"Addressing someone by title (Monsieur le Maire, Madame la Directrice) is a mark of formal respect."}]},
    {t:"Review: formal French",s:"Review",qs:[
      {q:"In 'Je vous saurais gré', which form of savoir is used?",opts:["the conditionnel","the futur","the subjonctif","the imparfait"],a:0,ex:"Saurais is the conditionnel of savoir, which makes the request polite."},
      {q:"Which hedge fits: 'C'est, ___, notre dernière chance.' (= so to speak)",opts:["pour ainsi dire","à vrai dire","en revanche","du coup"],a:0,ex:"Pour ainsi dire = so to speak; à vrai dire means to tell the truth, en revanche on the other hand."},
      {q:"Editing: which word should replace 'du coup' in formal writing?",opts:["par conséquent","en fait","bref","en gros"],a:0,ex:"Par conséquent expresses the same consequence formally; en fait, bref and en gros are informal."}]},
    {t:"Challenge: polishing the letter",s:"Challenge",qs:[
      {q:"Which sentence is correct at the top of a cover note?",opts:["Ci-joint les factures demandées.","Ci-jointes les factures demandées.","Ci-joints les factures demandées.","Ci-jointe les factures demandées."],a:0,ex:"At the start of a sentence, ci-joint is invariable: Ci-joint les factures."},
      {q:"Heavy: 'Nous procédons à l'envoi de votre commande.' Best lighter edit:",opts:["Nous expédions votre commande.","Nous procédons à expédier la commande.","Nous expédions à l'envoi la commande.","Nous procédons de l'envoi livré."],a:0,ex:"One precise verb (expédier) replaces the heavy procéder à + noun chain."},
      {q:"'Je vous saurais gré de bien vouloir me faire parvenir...' What register and function?",opts:["a very formal request","an informal suggestion","a formal apology","a neutral statement of fact"],a:0,ex:"Savoir gré + bien vouloir + faire parvenir (to send) is a highly formal way to ask for something."}]}
  ],
  // Module 6: Nominal Style & Professional Communication
  [
    {t:"Meeting vocabulary",s:"Vocabulary",qs:[
      {q:"'la mise en œuvre' means:",opts:["the implementation","the artwork","the workload","the job offer"],a:0,ex:"Mettre en œuvre = to put into practice; la mise en œuvre is its nominal form."},
      {q:"'faire le point sur' means:",opts:["to take stock of","to make a point about","to point at","to put an end to"],a:0,ex:"Faire le point = to review where things stand; it is a false friend of 'make a point'."},
      {q:"'Suite à notre échange' means:",opts:["Following our discussion","After our exchange of goods","Before our conversation","Despite our disagreement"],a:0,ex:"Un échange here is a conversation or exchange of views; suite à = following."}]},
    {t:"Word families and connectors",s:"Vocabulary",qs:[
      {q:"Noun from 'réduire':",opts:["la réduction","le réduisement","la réduisance","le réduissage"],a:0,ex:"Verbs in -uire often give nouns in -uction: réduire → la réduction, produire → la production."},
      {q:"Noun from 'reporter' (to postpone):",opts:["le report","la reportation","le reportage","la reporte"],a:0,ex:"Le report = postponement; le reportage is a news report, a different word."},
      {q:"Which connector adds a point, like 'en outre'?",opts:["par ailleurs","en revanche","pourtant","toutefois"],a:0,ex:"Par ailleurs adds information; en revanche, pourtant and toutefois introduce contrast."}]},
    {t:"Office sounds",s:"Pronunciation",qs:[
      {q:"Listen. How is 'œuvre' pronounced?",say:"la mise en œuvre",opts:["[œvʁ]","[ɔvʁ]","[uvʁ]","[ovʁe]"],a:0,ex:"The œ in œuvre is [œ], as in sœur and cœur; the final -e is silent."},
      {q:"Listen. What links 'en' and 'outre'?",say:"en outre",opts:["an n sound (liaison)","a t sound (liaison)","a z sound (liaison)","no link at all"],a:0,ex:"En before a vowel takes a compulsory liaison: [ɑ̃-nutʁ]."},
      {q:"Listen. In 'compte', which letters are silent?",say:"le compte rendu",opts:["the p and the final e","only the final e","the m and the t","none of them"],a:0,ex:"Compte is pronounced [kɔ̃t]: the p is silent, the m marks the nasal vowel and the final -e is mute."}]},
    {t:"Verb to noun",s:"Grammar",qs:[
      {q:"'Les ventes ont chuté.' → nominal:",opts:["la chute des ventes","le chutement des ventes","la chutation des ventes","les ventes chutées"],a:0,ex:"The noun from chuter is la chute, followed by de + the former subject."},
      {q:"'Le site va fermer.' → nominal:",opts:["la fermeture du site","le fermement du site","la fermation du site","le fermage du site"],a:0,ex:"The noun from fermer is la fermeture; le fermage is an unrelated word (tenant farming)."},
      {q:"'Le projet a été mis en œuvre.' → nominal:",opts:["la mise en œuvre du projet","le mettage en œuvre du projet","la mise en œuvre de le projet","le mis en œuvre du projet"],a:0,ex:"Mettre en œuvre becomes la mise en œuvre, and de + le contracts to du."}]},
    {t:"Nominal style in context",s:"Grammar",qs:[
      {q:"Turn into an agenda heading: 'Nous allons réorganiser le service.'",opts:["Réorganisation du service","Réorganiser du service","Réorganisé le service","La réorganisant du service"],a:0,ex:"Headings use a noun phrase: réorganiser → la réorganisation, often without the article."},
      {q:"Which sentence is correct in a price notice?",opts:["Suite à l'augmentation des coûts, le prix sera révisé.","Suite à l'augmentation de les coûts, le prix sera révisé.","Suite à augmenter les coûts, le prix sera révisé.","Suite à l'augmentement des coûts, le prix sera révisé."],a:0,ex:"Suite à takes a noun (l'augmentation), and de + les contracts to des."},
      {q:"Which nominalisation is NOT correct?",opts:["analyser → l'analysation","développer → le développement","livrer → la livraison","acquérir → l'acquisition"],a:0,ex:"The noun from analyser is l'analyse; the -ation suffix is common but not automatic."}]},
    {t:"Reading: an agenda and minutes",s:"Reading",qs:[
      {q:"Read: 'Ordre du jour : 1. Bilan du trimestre 2. Recrutement 3. Questions diverses.' What will be discussed second?",opts:["hiring","the quarterly review","any other business","the budget"],a:0,ex:"Recrutement means hiring; questions diverses is 'any other business'."},
      {q:"Read: 'Décisions prises : report du lancement au 1er mars. Actions à mener : Mme Roux contactera le fournisseur.' What was decided?",opts:["The launch is postponed to 1 March.","The launch takes place before March.","Mme Roux will leave the company.","The supplier will contact Mme Roux."],a:0,ex:"Report du lancement = postponement of the launch, here to 1 March."},
      {q:"Read: 'Les ventes progressent en Europe ; en revanche, le marché asiatique recule.' Which is true?",opts:["Sales in Asia are falling.","Sales are rising everywhere.","Sales in Europe are falling.","The Asian market is stable."],a:0,ex:"En revanche introduces the contrast, and reculer means to fall back."}]},
    {t:"Listening: a team meeting",s:"Listening",qs:[
      {q:"Listen. What will they do first?",say:"Faisons le point sur l'avancement du projet avant de passer au budget.",opts:["review the project's progress","discuss next year's budget","end the meeting early","hire a new project manager"],a:0,ex:"Faire le point sur l'avancement = to review progress; the budget comes after (avant de passer au budget)."},
      {q:"Listen. When will the new procedure be implemented?",say:"En outre, la mise en œuvre de la nouvelle procédure est reportée à septembre.",opts:["in September","immediately","next week","never"],a:0,ex:"Reportée à septembre = postponed to September."},
      {q:"Listen. What is the speaker sending?",say:"Suite à notre échange de ce matin, je vous transmets le compte rendu.",opts:["the minutes","the agenda","an invoice","a contract"],a:0,ex:"Le compte rendu is the written record of a meeting, i.e. the minutes."}]},
    {t:"Chairing a meeting",s:"Speaking",qs:[
      {q:"Chairing a meeting, you open with:",opts:["Je vous propose de passer en revue l'ordre du jour.","Bon, on commence, ou on attend encore longtemps ?","Alors, qui veut parler en premier, là ?","Salut tout le monde, on fait quoi aujourd'hui ?"],a:0,ex:"Passer en revue l'ordre du jour sets out the agenda formally; the others are casual."},
      {q:"You want to take the floor politely in a meeting:",opts:["Si vous me permettez, j'aimerais ajouter un point.","Attendez, laissez-moi parler, c'est mon tour !","Stop, j'ai un truc à dire, moi aussi.","Bon, écoutez-moi deux secondes, là."],a:0,ex:"Si vous me permettez + conditionnel (j'aimerais) asks for the floor courteously."},
      {q:"To close the meeting by agreeing on actions, you say:",opts:["Récapitulons les actions à mener et les responsables.","Bon, ben, on verra bien ce qui se passe ensuite.","C'est fini, tout le monde peut partir maintenant.","On s'en reparle un de ces jours, peut-être."],a:0,ex:"Récapitulons les actions à mener sums up who does what, the standard end of a meeting."}]},
    {t:"Professional emails",s:"Writing",qs:[
      {q:"Best opening for a professional email to a known contact, Mme Leroy:",opts:["Bonjour Madame Leroy,","Salut Madame Leroy,","Coucou Mme Leroy,","Hé, Madame Leroy !"],a:0,ex:"Bonjour Madame + surname is the standard polite opening for a known professional contact."},
      {q:"Fill the gap in a compte rendu: 'Points ___ : budget, calendrier, recrutement.'",opts:["abordés","abordées","abordants","aborder"],a:0,ex:"Points is masculine plural, so the past participle used as an adjective is abordés."},
      {q:"Choose the correctly spelled email closing.",opts:["Bien cordialement,","Bien cordialemant,","Bien cordiallement,","Bien cordialment,"],a:0,ex:"Cordialement = cordial + -ement, with one l and the ending -ment."}]},
    {t:"French business culture",s:"Culture",qs:[
      {q:"In a French professional email, 'Bien cordialement' is:",opts:["a standard polite closing","a very intimate closing","a closing for complaints only","an old-fashioned literary closing"],a:0,ex:"Bien cordialement is the everyday neutral-polite sign-off in professional emails."},
      {q:"Compared with 'Bien cordialement', 'Je vous prie d'agréer...' is:",opts:["more formal and letter-like","more casual and friendly","used only between colleagues","exactly the same register"],a:0,ex:"The full formula belongs to formal letters; cordialement suits ordinary professional emails."},
      {q:"In French business culture, using 'vous' with a new client is:",opts:["the expected default","a sign of coldness","only for older clients","reserved for letters"],a:0,ex:"Vouvoiement is the norm with clients and new contacts; tutoiement comes only if agreed."}]},
    {t:"Review: professional French",s:"Review",qs:[
      {q:"'en outre' means:",opts:["moreover","however","therefore","for example"],a:0,ex:"En outre adds a further point, like par ailleurs and de plus."},
      {q:"Nominal form of 'Les salariés ont participé':",opts:["la participation des salariés","le participement des salariés","la participance des salariés","les salariés participés"],a:0,ex:"Participer becomes la participation, and the former subject follows with des."},
      {q:"Which section of a compte rendu lists who will do what?",opts:["les actions à mener","l'ordre du jour","les points abordés","la liste des présents"],a:0,ex:"Les actions à mener assigns tasks and deadlines after the decisions."}]},
    {t:"Challenge: dense formal prose",s:"Challenge",qs:[
      {q:"Best nominal rewrite of 'Parce que les commandes ont fortement diminué, nous avons dû réduire la production.'",opts:["La forte baisse des commandes a entraîné une réduction de la production.","La forte diminuance des commandes a entraîné une réduisation de la production.","Les commandes fortement baissées ont entraîné la produisance réduite.","La baisse fortement des commandes a entraîné de réduire la production."],a:0,ex:"Baisse and réduction are the real nouns, the adverb fortement becomes the adjective forte, and entraîner links cause and effect."},
      {q:"Which connector fits: 'Le budget est validé ; ___, le calendrier reste à définir.'",opts:["en revanche","en outre","dès lors","par conséquent"],a:0,ex:"The second clause contrasts with the first, so en revanche fits; the others add or conclude."},
      {q:"Which connector could replace 'dès lors' in 'Le fournisseur a refusé ; dès lors, nous devons en trouver un autre.'?",opts:["par conséquent","en revanche","toutefois","par ailleurs"],a:0,ex:"Dès lors here draws a consequence, just like par conséquent."}]}
  ]
];
